async function uploadRemoteFile(file, metadata = {}, csrfToken = "") {
  const form = new FormData();
  form.append("file", file);
  form.append("module", metadata.module ?? "Docs");
  form.append("category", metadata.category ?? "");
  form.append("linkedType", metadata.linkedType ?? "");
  form.append("linkedId", metadata.linkedId ?? "");

  const response = await fetch(UPLOAD_ENDPOINT, {
    method: "POST",
    headers: {
      Accept: "application/json",
      ...(csrfToken ? { "X-CSRF-Token": csrfToken } : {}),
    },
    credentials: "include",
    body: form,
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok || payload.ok === false) {
    const error = new Error(payload.message || "Envoi du fichier impossible.");
    error.code = payload.code || `http_${response.status}`;
    throw error;
  }
  return payload;
}

async function postBackupAction(action, body = {}, csrfToken = "") {
  const response = await fetch(BACKUP_ENDPOINT, {
    method: "POST",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      ...(csrfToken ? { "X-CSRF-Token": csrfToken } : {}),
    },
    credentials: "include",
    body: JSON.stringify({ action, ...body }),
  });

  if (action === "create_backup" && response.ok) {
    const blob = await response.blob();
    const disposition = response.headers.get("Content-Disposition") || "";
    const match = disposition.match(/filename="?([^"]+)"?/i);
    return {
      ok: true,
      blob,
      filename: match?.[1] || `EKIMMO_Backup_${new Date().toISOString().slice(0, 10)}.json`,
    };
  }

  const payload = await response.json().catch(() => ({}));
  if (!response.ok || payload.ok === false) {
    const error = new Error(payload.message || "Action de sauvegarde indisponible.");
    error.code = payload.code || `http_${response.status}`;
    throw error;
  }
  return payload;
}

