function ContractsPage({
  activeTab,
  onTab,
  availableTabs = ["Contrats", "Génération de document", "Archives"],
  onAction,
  demoDataLoaded = true,
  contractsList = contracts,
  paymentsList = paymentRecords,
  propertiesList = [],
  activePropertiesList = [],
  ownersList = [],
  tenantsList = [],
  commissionsList = [],
  documentDraft = null,
  propertyPdfArchives = [],
  onArchiveDocument,
  documentArchiveSequence = 1,
  contractTimelines = {},
  contractDeadlines = {},
  detailRequest = null,
  onDetailRequestConsumed,
  onDetailReturn,
  filterRequest = null,
  onFilterRequestConsumed,
  currentUserName = defaultManagerName,
}) {
  const tabs = availableTabs.length ? availableTabs : ["Contrats", "Génération de document", "Archives"];
  const requestedTab = activeTab === "Factures & reçus" ? "Archives" : activeTab;
  const effectiveTab = tabs.includes(requestedTab) ? requestedTab : tabs[0];
  const activeContracts = contractsList.filter((contract) => contract.status !== "Archivé");
  useEffect(() => {
    if (requestedTab !== effectiveTab) onTab(effectiveTab);
  }, [effectiveTab, onTab, requestedTab]);

  return (
    <>
      <PageIntro
        title="Contrats & documents"
      />
      <Tabs tabs={tabs} active={effectiveTab} onChange={onTab} demo="contract-tabs" />
      {effectiveTab === "Contrats" && (
        <ContractsList
          onAction={onAction}
          contractsList={activeContracts}
          propertiesList={propertiesList}
          ownersList={ownersList}
          tenantsList={tenantsList}
          contractTimelines={contractTimelines}
          contractDeadlines={contractDeadlines}
          detailRequest={detailRequest}
          onDetailRequestConsumed={onDetailRequestConsumed}
          onDetailReturn={onDetailReturn}
          filterRequest={filterRequest}
          onFilterRequestConsumed={onFilterRequestConsumed}
        />
      )}
      {effectiveTab === "Génération de document" && (
        <DocumentGeneration
          onAction={onAction}
          documentDraft={documentDraft}
          demoDataLoaded={demoDataLoaded}
          onArchiveDocument={onArchiveDocument}
          documentArchiveSequence={documentArchiveSequence}
          propertiesList={activePropertiesList}
          ownersList={ownersList}
          tenantsList={tenantsList}
          paymentsList={paymentsList}
          commissionsList={commissionsList}
          currentUserName={currentUserName}
        />
      )}
      {effectiveTab === "Archives" && (
        <ArchivesView
          onAction={onAction}
          contractsList={contractsList}
          paymentsList={paymentsList}
          propertyPdfArchives={propertyPdfArchives}
          includeDemoRecords={demoDataLoaded}
          propertiesList={propertiesList}
          ownersList={ownersList}
          tenantsList={tenantsList}
          commissionsList={commissionsList}
        />
      )}
    </>
  );
}

function ContractsList({
  onAction,
  contractsList = contracts,
  propertiesList = [],
  ownersList = [],
  tenantsList = [],
  contractTimelines = {},
  contractDeadlines = {},
  detailRequest = null,
  onDetailRequestConsumed,
  onDetailReturn,
  filterRequest = null,
  onFilterRequestConsumed,
}) {
  const [selected, setSelected] = useState(contractsList[0] ?? null);
  const [query, setQuery] = useState("");
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [returnRequest, setReturnRequest] = useState(null);
  const [filters, setFilters] = useState({
    type: "Tous types",
    status: "Tous statuts",
    property: "Tous biens",
    owner: "Tous propriétaires",
    tenant: "Tous locataires",
    due: "Toutes échéances",
    signature: "Tous documents",
  });
  const { detailOpen, openDetail, closeDetail } = useDetailNavigation();
  const currentSelectedContract = selected ? contractsList.find((contract) => getContractKey(contract) === getContractKey(selected)) ?? selected : null;

  const openContract = (contract) => {
    setSelected(contract);
    setReturnRequest(null);
    openDetail();
  };

  useEffect(() => {
    if (!detailRequest?.contractKey) return;
    const requestedContract =
      contractsList.find((contract) => getContractKey(contract) === detailRequest.contractKey) ??
      contractsList[0] ??
      null;
    if (!requestedContract) return;

    setSelected(requestedContract);
    setReturnRequest(detailRequest);
    openDetail();
    onDetailRequestConsumed?.();
  }, [detailRequest?.nonce]);

  useEffect(() => {
    if (!filterRequest?.filters) return;
    setQuery("");
    setFiltersOpen(true);
    setFilters((current) => ({ ...current, ...filterRequest.filters }));
    closeDetail();
    onFilterRequestConsumed?.();
  }, [filterRequest?.nonce]);

  const closeContractDetail = () => {
    if (returnRequest?.returnTo) {
      onDetailReturn?.(returnRequest);
      setReturnRequest(null);
      return;
    }
    closeDetail();
  };

  const updateFilter = (key, value) => setFilters((current) => ({ ...current, [key]: value }));
  const resetFilters = () => {
    setQuery("");
    setFilters({
      type: "Tous types",
      status: "Tous statuts",
      property: "Tous biens",
      owner: "Tous propriétaires",
      tenant: "Tous locataires",
      due: "Toutes échéances",
      signature: "Tous documents",
    });
  };

  const filteredContracts = useMemo(() => {
    const search = normalizeSearch(query);
    return contractsList.filter((contract) => {
      const dueLabel = getContractDueLabel(contract);
      const displayState = getContractDisplayState(contract);
      const signatureMissing = !hasSignedContractDocument(contract);
      const haystack = normalizeSearch(`${contract.number} ${contract.type} ${contract.property} ${contract.owner} ${contract.client} ${contract.status} ${displayState.label} ${signatureMissing ? "Document signé manquant" : "Document signé"} ${dueLabel}`);
      const typeMatch = filters.type === "Tous types" || contract.type === filters.type;
      const statusMatch =
        filters.status === "Tous statuts" ||
        contract.status === filters.status ||
        displayState.label === filters.status ||
        (filters.status === "Actif" && (["À échéance", "Échéance proche", "Suivi"].includes(contract.status) || displayState.label === "Échéance proche")) ||
        (filters.status === "Document signé manquant" && signatureMissing);
      const propertyMatch = filters.property === "Tous biens" || contract.property === filters.property;
      const ownerMatch = filters.owner === "Tous propriétaires" || contract.owner === filters.owner;
      const tenantMatch = filters.tenant === "Tous locataires" || contract.client === filters.tenant;
      const dueMatch = contractMatchesDueFilter(contract, filters.due);
      const signatureMatch =
        filters.signature === "Tous documents" ||
        (filters.signature === "Signé" && !signatureMissing) ||
        (filters.signature === "À signer" && signatureMissing) ||
        (filters.signature === "Archivé" && contract.status === "Archivé");
      return (!search || haystack.includes(search)) && typeMatch && statusMatch && propertyMatch && ownerMatch && tenantMatch && dueMatch && signatureMatch;
    });
  }, [contractsList, filters, query]);

  return (
    <>
      <Panel className="filter-panel">
        <div className="filters-row">
          <label className="field search-field">
            <Search size={19} />
            <input placeholder="Rechercher un contrat, bien, propriétaire..." value={query} onChange={(event) => setQuery(event.target.value)} />
          </label>
          <select value={filters.type} onChange={(event) => updateFilter("type", event.target.value)}><option>Tous types</option><option>Contrat de location</option><option>Mandat de gestion</option></select>
          <select value={filters.status} onChange={(event) => updateFilter("status", event.target.value)}><option>Tous statuts</option><option>Actif</option><option>Suivi</option><option>Échéance proche</option><option>Expiré</option><option>Document signé manquant</option><option>Archivé</option></select>
          <select value={filters.property} onChange={(event) => updateFilter("property", event.target.value)}><option>Tous biens</option>{propertiesList.map((property) => <option key={property.code}>{property.name}</option>)}</select>
          <select value={filters.owner} onChange={(event) => updateFilter("owner", event.target.value)}><option>Tous propriétaires</option>{ownersList.map((owner) => <option key={owner.id}>{owner.name}</option>)}</select>
          <select value={filters.tenant} onChange={(event) => updateFilter("tenant", event.target.value)}><option>Tous locataires</option>{tenantsList.map((tenant) => <option key={tenant.id}>{tenant.name}</option>)}</select>
          <select value={filters.due} onChange={(event) => updateFilter("due", event.target.value)}><option>Toutes échéances</option><option>Cette semaine</option><option>Ce mois</option><option>Cette année</option></select>
          <Button onClick={() => setFiltersOpen((value) => !value)}><Filter size={17} /> Filtres</Button>
        </div>
        {filtersOpen && (
          <div className="advanced-filters client-advanced-filters">
            <label>Document<select value={filters.signature} onChange={(event) => updateFilter("signature", event.target.value)}>
              <option>Tous documents</option>
              <option>Signé</option>
              <option>À signer</option>
              <option>Archivé</option>
            </select></label>
            <Button compact onClick={resetFilters}>Réinitialiser</Button>
            <span className="muted">{filteredContracts.length} contrat(s) affiché(s)</span>
          </div>
        )}
      </Panel>
      {detailOpen && currentSelectedContract ? (
        <DetailPageShell title="Fiche contrat" subtitle={currentSelectedContract.number} onBack={closeContractDetail}>
          <ContractProfilePanel
            contract={currentSelectedContract}
            propertiesList={propertiesList}
            tenantsList={tenantsList}
            onAction={onAction}
            timelineEntries={contractTimelines[getContractKey(currentSelectedContract)] ?? []}
            customDeadlines={contractDeadlines[getContractKey(currentSelectedContract)] ?? []}
          />
        </DetailPageShell>
      ) : (
      <section className="client-list-workspace" data-demo="contracts-workspace">
        <Panel title="Liste des contrats">
          <DataTable
            columns={["Numéro contrat", "Type", "Bien", "Propriétaire", "Locataire / client", "Date début", "Date fin", "Statut", "Échéance", "Actions"]}
            rows={filteredContracts.map((contract) => [
              contract.number,
              contract.type,
              contract.property,
              contract.owner,
              contract.client,
              contract.start,
              contract.end,
              <ContractStatusStack contract={contract} />,
              getContractDueLabel(contract),
              <div className="table-actions">
                <Button compact onClick={() => openContract(contract)}><Eye size={16} /> Fiche</Button>
                <Button compact onClick={() => onAction("Renouveler contrat", { contract })}><RefreshCw size={15} /> Renouveler</Button>
                <Button compact onClick={() => onAction("Resilier contrat", { contract })}><XCircle size={15} /> Résilier</Button>
                <Button compact onClick={() => onAction("Renouveler contrat", { contract })}><FileText size={15} /> Avenant</Button>
                <Button compact onClick={() => onAction("Archiver contrat", { contract })}><Archive size={15} /> Archiver</Button>
              </div>,
            ])}
          />
        </Panel>
      </section>
      )}
    </>
  );
}

function ContractStatusStack({ contract }) {
  const displayState = getContractDisplayState(contract);
  const signatureMissing = !hasSignedContractDocument(contract);

  return (
    <span className="contract-badge-stack">
      <Badge label={displayState.label} />
      {signatureMissing && <Badge label="Document signé manquant" />}
    </span>
  );
}

function ContractProfilePanel({ contract, propertiesList = [], tenantsList = [], onAction, timelineEntries = [], customDeadlines = [] }) {
  const property = propertiesList.find((item) => item.name === contract.property);
  const financials = getContractFinancials(contract, propertiesList, tenantsList);
  const directOwnerCollection = property && !isAgencyCollectedProperty(property.name, propertiesList);
  const deadlines = getContractDeadlines(contract, financials, customDeadlines);
  const timeline = getContractTimeline(contract, property, timelineEntries);
  const nextRent = contract.nextDueDate ?? deadlines.find((item) => item.type === "Prochain loyer")?.date ?? "05/07/2026";
  const displayState = getContractDisplayState(contract);
  const signatureMissing = !hasSignedContractDocument(contract);

  return (
    <Panel title="Fiche contrat" className="profile-panel">
      <div className="profile-header">
        <div className="round-icon">
          <FileText size={22} />
        </div>
        <div>
          <h3>{contract.number}</h3>
          <p>{contract.type}</p>
          <div className="contract-header-badges">
            <Badge label={displayState.label} />
            {signatureMissing && <Badge label="Document signé manquant" />}
          </div>
        </div>
      </div>
      <div className="simple-list">
        <p><span>Parties concernées</span><strong>{contract.owner} / {contract.client}</strong></p>
        <button className="info-link-row" onClick={() => onAction("Ouvrir bien contrat", { contract })}><span>Bien</span><strong>{contract.property}</strong></button>
        <button className="info-link-row" onClick={() => onAction("Ouvrir proprietaire contrat", { contract })}><span>Propriétaire</span><strong>{contract.owner}</strong></button>
        <button className="info-link-row" onClick={() => onAction("Ouvrir locataire contrat", { contract })}><span>Locataire</span><strong>{contract.client}</strong></button>
        <p><span>Dates</span><strong>{contract.start} - {contract.end}</strong></p>
        <p><span>Montant</span><strong>{financials.amount}</strong></p>
        <p><span>Mode financier</span><strong>{contract.financialMode ?? property?.financialMode ?? "À définir"}</strong></p>
        <p><span>Caution</span><strong>{financials.deposit}</strong></p>
        <p><span>Commission</span><strong>{financials.commission}</strong></p>
        <p><span>Statut</span><span className="contract-badge-stack"><Badge label={displayState.label} /></span></p>
        <button className="info-link-row" onClick={() => onAction("Document signe contrat", { contract })}><span>Document signé</span><strong>{hasSignedContractDocument(contract) ? getSignedContractFileName(contract) : "À importer"}</strong></button>
        {contract.amendmentReference && <p><span>Avenant</span><strong>{contract.amendmentReference}</strong></p>}
        <button className="info-link-row" onClick={() => onAction("Actions echeance contrat", { contract })}><span>Échéance</span><strong>{getContractDueLabel(contract)}</strong></button>
        <p><span>Prochain loyer</span><strong>{nextRent}</strong></p>
        <p><span>Fin du contrat</span><strong>{contract.end}</strong></p>
        <p><span>Alerte</span><span className="contract-badge-stack"><Badge label={signatureMissing ? "Document signé manquant" : displayState.label === "Échéance proche" ? "Échéance proche" : "Planifiée"} /></span></p>
      </div>
      {signatureMissing && (
        <div className="contract-alert-card">
          <span><AlertTriangle size={20} /></span>
          <div>
            <strong>Document signé manquant</strong>
            <p>Le contrat peut rester suivi, mais la version signée doit être importée pour compléter les archives.</p>
          </div>
          <Button compact onClick={() => onAction("Importer contrat signe", { contract })}><Upload size={15} /> Importer contrat signé</Button>
        </div>
      )}
      {directOwnerCollection && (
        <div className="notice">
          Encaissement direct propriétaire : le contrat reste suivi par E.K immo, mais les loyers ne sont pas ajoutés aux paiements agence à collecter.
        </div>
      )}
      <div className="profile-section">
        <div className="section-heading-row">
          <h3>Échéances</h3>
          <Button compact onClick={() => onAction("Gerer echeances contrat", { contract })}><CalendarDays size={16} /> Gérer les échéances</Button>
        </div>
        <div className="deadline-list">
          {deadlines.map((deadline) => (
            <div className="deadline-row" key={`${deadline.type}-${deadline.date}-${deadline.comment}`}>
              <span>
                <strong>{deadline.type}</strong>
                <small>{deadline.comment}</small>
              </span>
              <Badge label={deadline.date} />
            </div>
          ))}
        </div>
      </div>
      <div className="timeline compact-timeline">
        {timeline.map((entry) => (
          <p key={`${entry.date}-${entry.action}-${entry.comment}`}>
            <strong>{entry.action}</strong>
            <span>{entry.date} - {entry.user}{entry.comment ? ` - ${entry.comment}` : ""}</span>
          </p>
        ))}
      </div>
      <div className="stack-actions">
        <Button variant="primary" onClick={() => onAction("Modifier contrat", { contract })}><Pencil size={17} /> Modifier</Button>
        <Button onClick={() => onAction("Renouveler contrat", { contract })}><RefreshCw size={17} /> Renouveler</Button>
        <Button onClick={() => onAction("Resilier contrat", { contract })}><XCircle size={17} /> Résilier</Button>
        <Button onClick={() => onAction("PDF contrat", { contract })}><Download size={17} /> PDF</Button>
        <Button onClick={() => onAction("Imprimer contrat", { contract })}><Printer size={17} /> Imprimer</Button>
        <Button onClick={() => onAction("Contrat signé", { contract })}><Upload size={17} /> Contrat signé</Button>
        <Button onClick={() => onAction("Archiver contrat", { contract })}><Archive size={17} /> Archiver</Button>
        <Button onClick={() => onAction("Ouvrir bien contrat", { contract })}><Home size={17} /> Voir fiche bien</Button>
        <Button onClick={() => onAction("Ouvrir proprietaire contrat", { contract })}><UserRound size={17} /> Voir propriétaire</Button>
        <Button onClick={() => onAction("Ouvrir locataire contrat", { contract })}><UsersRound size={17} /> Voir locataire</Button>
      </div>
    </Panel>
  );
}

function getContractDeadlines(contract, financials, customDeadlines = []) {
  const base = [
    { type: "Prochain loyer", date: contract.nextDueDate ?? "05/07/2026", comment: financials.amount },
    { type: "Prochaine révision", date: contract.revisionDate ?? "01/01/2027", comment: "Indexation annuelle à valider" },
    { type: "Fin du contrat", date: contract.end, comment: "Contrôler renouvellement ou sortie" },
    { type: "Alerte planifiée", date: contract.number === "CON-2025-088" ? "Dans 32 jours" : "30 jours avant", comment: "Notification agent et manager" },
    { type: "Renouvellement prévu", date: contract.renewalDate ?? "À confirmer", comment: contract.status === "Renouvelé" ? "Renouvellement enregistré" : "Option à valider" },
  ];

  if (contract.status === "Résilié" || contract.terminationDate) {
    base.push({ type: "Résiliation prévue", date: contract.terminationDate ?? contract.end, comment: "Sortie à suivre" });
  }

  return [...customDeadlines.map((item) => ({
    type: item.type,
    date: item.date,
    comment: `${item.reminder} · ${item.notify} · ${item.comment}`,
  })), ...base];
}

function getContractTimeline(contract, property, timelineEntries = []) {
  const contractAgent = contract.signedImportedBy ?? contract.generatedBy ?? property?.agent ?? defaultManagerName;
  const signatureEntry = hasSignedContractDocument(contract)
    ? [{ date: contract.signedAt ?? contract.signedImportedAt ?? "18/06/2026", user: contract.signedImportedBy ?? contractAgent, action: "Signature ajoutée", comment: "Document signé archivé" }]
    : [{ date: "21/06/2026", user: "Système", action: "Alerte document", comment: "Document signé manquant" }];

  return [
    ...timelineEntries,
    { date: contract.start, user: contract.owner, action: "Contrat créé", comment: `${contract.number} lié à ${contract.property}` },
    { date: contract.start, user: contractAgent, action: "Génération PDF", comment: "Modèle E.K immo alimenté et prêt à archiver" },
    ...signatureEntry,
    { date: contract.end, user: "Système", action: "Alerte envoyée", comment: getContractDueLabel(contract) },
    { date: "20/06/2026", user: contractAgent, action: "Dernière vérification", comment: `${property?.status ?? "Actif"} · fiche bien liée` },
  ];
}
function getContractFinancials(contract, propertiesList = [], tenantsList = []) {
  const property = propertiesList.find((item) => item.name === contract.property);
  const tenant = tenantsList.find((item) => item.name === contract.client);
  const commissionRate = contract.commissionRate ?? property?.recurringCommissionRate;
  const commissionBase = contract.commissionBase ?? property?.recurringCommissionBase ?? "Loyer encaissé";

  return {
    amount: tenant?.rent ?? (property ? `${property.price} ${property.period}` : "À définir"),
    deposit: tenant?.deposit ?? property?.deposit ?? "À définir",
    commission: commissionRate ? `${commissionRate} sur ${commissionBase}` : contract.commission ?? property?.commission ?? "À définir",
  };
}

const contractReferenceDate = new Date(2026, 5, 21);
const contractSoonThresholdDays = 45;

function parseContractDate(value) {
  if (!value || typeof value !== "string") return null;
  const match = value.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (!match) return null;
  const [, day, month, year] = match;
  return new Date(Number(year), Number(month) - 1, Number(day));
}

function getDaysUntilContractEnd(contract) {
  const endDate = parseContractDate(contract.end);
  if (!endDate) return null;
  return Math.ceil((endDate.getTime() - contractReferenceDate.getTime()) / 86400000);
}

function getContractDisplayState(contract = {}) {
  const status = contract.status ?? "";
  const normalizedStatus = normalizeSearch(status);
  const daysUntilEnd = getDaysUntilContractEnd(contract);

  if (normalizedStatus === "archive") {
    return { label: "Archivé", description: "Contrat classé dans les archives.", daysUntilEnd };
  }

  if (normalizedStatus === "resilie") {
    return { label: "Résilié", description: "Contrat clôturé avec historique conservé.", daysUntilEnd };
  }

  if (normalizedStatus === "suivi") {
    return { label: "Suivi", description: "Contrat en suivi opérationnel.", daysUntilEnd };
  }

  if (normalizedStatus === "expire" || (daysUntilEnd !== null && daysUntilEnd < 0)) {
    return { label: "Expiré", description: "Contrat arrivé à échéance.", daysUntilEnd };
  }

  if (normalizedStatus.includes("echeance") || (daysUntilEnd !== null && daysUntilEnd <= contractSoonThresholdDays)) {
    return { label: "Échéance proche", description: "Contrat à renouveler, résilier ou archiver.", daysUntilEnd };
  }

  if (normalizedStatus === "actif") {
    return { label: "Actif", description: "Contrat actif et suivi normalement.", daysUntilEnd };
  }

  return { label: status || "À qualifier", description: "Suivi requis.", daysUntilEnd };
}

function getContractDueLabel(contract) {
  const displayState = getContractDisplayState(contract);
  if (displayState.label === "Archivé") return "Archivé";
  if (displayState.label === "Expiré") return "Expiré";
  if (displayState.label === "Échéance proche") {
    if (displayState.daysUntilEnd === null) return "Échéance proche";
    return displayState.daysUntilEnd <= 0 ? "Échéance aujourd'hui" : `${displayState.daysUntilEnd} jours`;
  }
  if (contract.end === "Vendu") return "Clôturé";
  return "En cours";
}

function DocumentGeneration({
  onAction,
  documentDraft = null,
  demoDataLoaded = true,
  onArchiveDocument,
  documentArchiveSequence = 1,
  propertiesList = [],
  ownersList = [],
  tenantsList = [],
  paymentsList = [],
  commissionsList = [],
  currentUserName = defaultManagerName,
}) {
  const neutralProperty = {
    code: "",
    name: "Bien à renseigner",
    type: "Bien immobilier",
    district: "Quartier à renseigner",
    address: "Adresse à renseigner",
    owner: "Propriétaire à renseigner",
    tenant: "Locataire à renseigner",
    price: "0 FCFA",
    period: "",
    deposit: "0 FCFA",
    commission: "0%",
    financialMode: "Mode financier à renseigner",
    tags: [],
  };
  const neutralOwner = { name: "Propriétaire à renseigner", phone: "", email: "", charges: "0 FCFA", commission: "0 FCFA", balance: "0 FCFA" };
  const neutralTenant = { name: "Locataire à renseigner", phone: "", email: "", rent: "0 FCFA", deposit: "0 FCFA", property: "" };
  const firstProperty = propertiesList[0] ?? neutralProperty;
  const firstOwner = ownersList.find((item) => item.name === firstProperty.owner) ?? ownersList[0] ?? neutralOwner;
  const firstTenant = tenantsList.find((item) => item.name === firstProperty.tenant || item.property === firstProperty.name) ?? tenantsList[0] ?? neutralTenant;
  const firstPayment = paymentsList.find((item) => item.property === firstProperty.name || item.tenant === firstTenant.name) ?? paymentsList[0];
  const firstCommission = commissionsList.find((item) => item.property === firstProperty.name || item.owner === firstOwner.name) ?? commissionsList[0] ?? { operation: "", property: firstProperty.name, owner: firstOwner.name, commission: "0 FCFA", rate: "0%" };
  const defaultInvoice = firstPayment
    ? {
      number: firstPayment.receipt && firstPayment.receipt !== "Non généré" ? firstPayment.receipt : makeDocumentNumber("FAC", 55),
      type: "Facture",
      client: firstPayment.tenant ?? firstTenant.name,
      property: firstPayment.property ?? firstProperty.name,
      amount: firstPayment.paid ?? firstPayment.expected ?? firstProperty.price ?? "0 FCFA",
      date: firstPayment.date ?? "",
      status: firstPayment.receipt && firstPayment.receipt !== "Non généré" ? "Archivé" : "Brouillon",
    }
    : { number: "", type: "Facture", client: firstTenant.name, property: firstProperty.name, amount: firstProperty.price || "0 FCFA", date: "" };
  const defaultData = documentDraft?.data ?? (demoDataLoaded ? {
    invoice: defaultInvoice,
    payment: firstPayment ?? { reference: "", receipt: "", tenant: firstTenant.name, property: firstProperty.name, paid: "0 FCFA", balance: "0 FCFA", date: "" },
    commission: firstCommission,
    property: firstProperty,
    owner: firstOwner,
    tenant: firstTenant,
    currentUserName,
  } : {
    invoice: { number: "", type: "Facture", client: "", property: "", amount: "0 FCFA", date: "" },
    payment: { reference: "", receipt: "", tenant: "", property: "", paid: "0 FCFA", balance: "0 FCFA", date: "" },
    commission: { operation: "", property: "", owner: "", commission: "0 FCFA", rate: "0%" },
    property: neutralProperty,
    owner: neutralOwner,
    tenant: neutralTenant,
    currentUserName,
  });
  const draftTitle = documentDraft?.data?.draftStatus === "Brouillon"
    ? `Reprendre le brouillon - ${documentDraft.data.draftReference}`
    : null;

  return (
    <DocumentStudio
      initialTemplate={documentDraft?.templateKey ?? "facture"}
      autoOpen={Boolean(documentDraft)}
      title={draftTitle ?? (documentDraft ? `Générer un document - ${documentTemplates.find((item) => item.key === documentDraft.templateKey)?.label ?? "Document"}` : "Atelier de génération documentaire")}
      onAction={onAction}
      onArchiveDocument={onArchiveDocument}
      documentArchiveSequence={documentArchiveSequence}
      data={defaultData}
    />
  );
}

