function TemplatesAdmin({ onAction, archives = [], onArchiveTemplate }) {
  const [templateArchives, setTemplateArchives] = useState(archives ?? []);
  const [feedback, setFeedback] = useState("");
  useEffect(() => {
    setTemplateArchives(archives ?? []);
  }, [archives]);
  const archivedKeys = templateArchives.map((archive) => archive.key);
  const availableTemplates = documentTemplates.filter((template) => !archivedKeys.includes(template.key));

  const archiveTemplate = async ({ template, values }) => {
    try {
      await onArchiveTemplate?.({ template, values });
      setFeedback("Modèle archivé.");
    } catch (error) {
      setFeedback(error.message || "Impossible d'archiver le modèle.");
      return;
    }
    const archive = {
      id: `template-archive-${template.key}-${templateArchives.length + 1}`,
      key: template.key,
      label: template.label,
      source: template.source,
      format: template.format,
      reason: values.reason,
      comment: values.comment,
      confirmed: values.confirmed,
      date: "26/06/2026",
      status: "Archivé",
    };
    setTemplateArchives((current) => [
      archive,
      ...current.filter((item) => item.key !== template.key),
    ]);
  };

  return (
    <section className="templates-admin-view">
      <DocumentStudio
        initialTemplate={availableTemplates[0]?.key ?? "facture"}
        title="Atelier des modèles E.K immo"
        onAction={onAction}
        data={{
          invoice: invoices[0],
          payment: paymentRecords[0],
          commission: commissions[0],
          property: makeEmptyProperty({ name: "Bien exemple", owner: "Propriétaire exemple", tenant: "Locataire exemple" }),
          owner: { name: "Propriétaire exemple" },
          tenant: { name: "Locataire exemple", property: "Bien exemple" },
        }}
        availableTemplates={availableTemplates}
        onArchiveTemplate={archiveTemplate}
      />
      {feedback && <p className={feedback.includes("Impossible") ? "form-alert" : "form-success"}>{feedback}</p>}
      <Panel title="Archives des modèles" className="template-archives-panel">
        {templateArchives.length === 0 ? (
          <div className="empty-state compact-empty">
            <Archive size={22} />
            <h3>Aucun modèle archivé</h3>
            <p>Les modèles archivés seront masqués de la génération et resteront consultables ici.</p>
          </div>
        ) : (
          <DataTable
            columns={["Modèle", "Fichier source", "Format", "Motif", "Commentaire", "Date", "Statut"]}
            rows={templateArchives.map((archive) => [
              archive.label,
              archive.source,
              archive.format,
              archive.reason,
              archive.comment,
              archive.date,
              <Badge label={archive.status} />,
            ])}
          />
        )}
      </Panel>
    </section>
  );
}

