function LoginScreen({ onLogin }) {
  const [forgotPasswordOpen, setForgotPasswordOpen] = useState(false);
  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [loginError, setLoginError] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const submitLogin = async (event) => {
    event.preventDefault();
    if (!identifier.trim() || !password.trim()) {
      setLoginError("Renseignez votre identifiant et votre mot de passe.");
      return;
    }

    setSubmitting(true);
    try {
      setLoginError("");
      await onLogin({ identifier, password });
    } catch (error) {
      setLoginError(error.message || "Identifiant ou mot de passe incorrect.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <>
      <main className="login-screen">
        <form className="login-card" onSubmit={submitLogin}>
          <div className="login-brand">
            <img src={ekimmoAssets.logo} alt="E.K immo" />
            <div>
              <strong>E.K immo</strong>
              <span>Gestion immobilière</span>
            </div>
          </div>
          <h1>Connexion</h1>
          <p>Accédez à votre espace de gestion immobilière.</p>
          <label>Email ou identifiant
            <input
              value={identifier}
              onChange={(event) => {
                setIdentifier(event.target.value);
                setLoginError("");
              }}
              placeholder="Identifiant utilisateur"
              autoComplete="username"
            />
          </label>
          <label>Mot de passe
            <input
              type="password"
              value={password}
              onChange={(event) => {
                setPassword(event.target.value);
                setLoginError("");
              }}
              placeholder="Mot de passe"
              autoComplete="current-password"
            />
          </label>
          <button className="primary-wide" type="submit" disabled={submitting}>{submitting ? "Connexion..." : "Se connecter"}</button>
          <button className="link-button" type="button" onClick={() => setForgotPasswordOpen(true)}>Mot de passe oublié ?</button>
          {loginError && <div className="error-demo">{loginError}</div>}
        </form>
      </main>
      {forgotPasswordOpen && <ForgotPasswordModal onClose={() => setForgotPasswordOpen(false)} />}
    </>
  );
}

function ForgotPasswordModal({ onClose }) {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState(null);
  const [message, setMessage] = useState("");
  const [detail, setDetail] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const isValidEmail = (value) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);

  const sendResetLink = async () => {
    const normalizedEmail = email.trim().toLowerCase();
    if (!normalizedEmail) {
      setStatus("error");
      setMessage("Renseignez votre adresse email.");
      setDetail("");
      return;
    }
    if (!isValidEmail(normalizedEmail)) {
      setStatus("error");
      setMessage("Renseignez une adresse email valide.");
      setDetail("");
      return;
    }

    setSubmitting(true);
    try {
      await forgotPasswordRemote(normalizedEmail);
      setStatus("success");
      setMessage("Lien de réinitialisation envoyé.");
      setDetail("Si cette adresse est associée à un compte, un lien de réinitialisation a été envoyé.");
    } catch (error) {
      setStatus("error");
      setMessage(error.message || "Impossible d'envoyer le lien pour le moment. Veuillez réessayer.");
      setDetail("");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="modal-backdrop" role="presentation" onMouseDown={onClose}>
      <section className="modal-card compact-modal forgot-password-modal" role="dialog" aria-modal="true" aria-labelledby="forgot-password-title" onMouseDown={(event) => event.stopPropagation()}>
        <button className="modal-close" onClick={onClose}>×</button>
        <div className="round-icon">
          <LockKeyhole size={22} />
        </div>
        <h2 id="forgot-password-title">Mot de passe oublié</h2>
        <p>Entrez l’adresse email associée à votre compte. Un lien de réinitialisation vous sera envoyé.</p>
        <label>Email utilisateur
          <input
            type="email"
            value={email}
            onChange={(event) => {
              setEmail(event.target.value);
              setStatus(null);
              setMessage("");
              setDetail("");
            }}
            placeholder="exemple@ekimmo.ml"
          />
        </label>
        {status && (
          <div className={`modal-status ${status}`} role="status">
            <strong>{message}</strong>
            {detail && <span>{detail}</span>}
          </div>
        )}
        <div className="action-row compact-row">
          <Button onClick={onClose}>Annuler</Button>
          <Button variant="primary" onClick={sendResetLink} disabled={submitting}><Mail size={17} /> {submitting ? "Envoi..." : "Envoyer le lien"}</Button>
        </div>
      </section>
    </div>
  );
}

