function getMonthShortLabel(period) {
  const normalized = normalizeSearch(period);
  const months = [
    ["janvier", "Jan"],
    ["fevrier", "Fév"],
    ["mars", "Mar"],
    ["avril", "Avr"],
    ["mai", "Mai"],
    ["juin", "Juin"],
    ["juillet", "Juil"],
    ["aout", "Août"],
    ["septembre", "Sep"],
    ["octobre", "Oct"],
    ["novembre", "Nov"],
    ["decembre", "Déc"],
  ];
  return months.find(([key]) => normalized.includes(key))?.[1] ?? String(period || "Période");
}

function buildRentMonthlyEvolution(rentRowsList = []) {
  const rows = rentRowsList.filter((row) => parseFCFA(row.expected) > 0);
  if (!rows.length) return [];

  const grouped = rows.reduce((acc, row) => {
    const label = getMonthShortLabel(row.period);
    const current = acc[label] ?? { month: label, expected: 0, collected: 0 };
    current.expected += parseFCFA(row.expected);
    current.collected += parseFCFA(row.paid);
    acc[label] = current;
    return acc;
  }, {});

  return Object.values(grouped).slice(-6);
}

function RentBars({ rentRowsList = [] }) {
  const monthlyEvolution = buildRentMonthlyEvolution(rentRowsList);

  if (!monthlyEvolution.length) {
    return (
      <div className="rent-chart empty-chart" data-demo="dashboard-rent-chart">
        <p>Aucune donnée disponible pour cette période.</p>
      </div>
    );
  }

  const maxExpected = Math.max(...monthlyEvolution.map((item) => item.expected), 1);
  const bars = monthlyEvolution.map((item, index, items) => {
    const unpaid = Math.max(item.expected - item.collected, 0);
    const collectionRate = item.expected ? Math.round((item.collected / item.expected) * 100) : 0;

    return {
      ...item,
      value: Math.round((item.expected / maxExpected) * 100),
      expectedLabel: formatFCFA(item.expected),
      collectedLabel: formatFCFA(item.collected),
      unpaidLabel: formatFCFA(unpaid),
      collectionRate,
      tone: index === items.length - 1 ? "active" : "soft",
    };
  });

  return (
    <div className="rent-chart" data-demo="dashboard-rent-chart">
      <div className="bars">
        {bars.map((bar) => (
          <button
            className="bar-button"
            key={bar.month}
            style={{ "--height": `${bar.value}%` }}
            aria-label={`${bar.month}: ${bar.expectedLabel} attendus, ${bar.collectedLabel} encaissés, ${bar.unpaidLabel} impayés, ${bar.collectionRate}% d'encaissement`}
          >
            <i className={bar.tone} />
            <span className="chart-flyout rent-flyout">
              <strong>{bar.month}</strong>
              <span><em>Loyers attendus</em><b>{bar.expectedLabel}</b></span>
              <span><em>Loyers encaissés</em><b>{bar.collectedLabel}</b></span>
              <span><em>Impayés</em><b>{bar.unpaidLabel}</b></span>
              <span><em>Taux d'encaissement</em><b>{bar.collectionRate}%</b></span>
            </span>
          </button>
        ))}
      </div>
      <div className="months">
        {bars.map((bar) => (
          <span key={bar.month}>{bar.month}</span>
        ))}
      </div>
    </div>
  );
}

