function MoneyInput({ value, onChange, readOnly = false, placeholder = "0", ...props }) {
  const rawValue = value === null || value === undefined ? "" : String(value);
  const hasAmount = /\d/.test(rawValue);
  const amount = parseFCFA(value);
  const displayValue = !rawValue || !hasAmount
    ? ""
    : new Intl.NumberFormat("fr-FR").format(amount);

  const handleChange = (event) => {
    const nextAmount = parseFCFA(event.target.value);
    onChange(nextAmount > 0 ? formatFCFA(nextAmount) : "");
  };

  return (
    <span className={`money-input ${readOnly ? "readonly" : ""}`}>
      <input
        {...props}
        inputMode="numeric"
        value={displayValue}
        onChange={handleChange}
        readOnly={readOnly}
        placeholder={placeholder}
      />
      <b>FCFA</b>
    </span>
  );
}

function PercentInput({ value, onChange, readOnly = false, placeholder = "0", ...props }) {
  const numericValue = String(value ?? "").replace("%", "").replace(",", ".").replace(/[^\d.]/g, "");

  const handleChange = (event) => {
    const raw = event.target.value.replace(",", ".").replace(/[^\d.]/g, "");
    onChange(raw ? `${raw}%` : "");
  };

  return (
    <span className={`money-input percent-input ${readOnly ? "readonly" : ""}`}>
      <input
        {...props}
        inputMode="decimal"
        value={numericValue}
        onChange={handleChange}
        readOnly={readOnly}
        placeholder={placeholder}
      />
      <b>%</b>
    </span>
  );
}

function ServerFileInput({
  label,
  value = "",
  accept = ".pdf,.jpg,.jpeg,.png,.webp,.doc,.docx",
  multiple = false,
  onUpload,
  onUploaded,
  onFilesSelected,
  metadata = {},
  fallbackText = "Aucun fichier sélectionné",
  small,
  className = "",
}) {
  const [display, setDisplay] = useState(value);
  const [status, setStatus] = useState("");
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    setDisplay(value);
  }, [value]);

  const uploadFiles = async (event) => {
    const files = Array.from(event.target.files ?? []);
    if (!files.length) return;
    onFilesSelected?.(multiple ? files : files[0], files);
    setBusy(true);
    setStatus("Envoi du fichier...");
    try {
      const uploads = [];
      if (onUpload) {
        for (const file of files) {
          uploads.push(await onUpload(file, metadata));
        }
      } else {
        uploads.push(...files.map((file) => ({ originalName: file.name, url: "" })));
      }
      const labelText = uploads.map((upload) => upload.originalName || upload.name).filter(Boolean).join(", ");
      setDisplay(labelText);
      setStatus("Fichier enregistré.");
      onUploaded?.(multiple ? uploads : uploads[0]);
    } catch (error) {
      setStatus(error.message || "Envoi du fichier impossible.");
    } finally {
      setBusy(false);
      event.target.value = "";
    }
  };

  return (
    <label className={className}>
      {label}
      <input type="file" accept={accept} multiple={multiple} onChange={uploadFiles} disabled={busy} />
      <small>{status || display || small || fallbackText}</small>
    </label>
  );
}

function getInitials(name) {
  return name
    .split(" ")
    .filter(Boolean)
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

function Badge({ label }) {
  const tone = statusTone(label);
  return <span className={`badge ${tone}`}>{label}</span>;
}

function statusTone(label) {
  if (["Disponible", "Actif", "À jour", "Payé", "Payée", "Validée", "Déduite", "Conclu", "Archivé", "Imprimé", "Généré", "Réalisée", "Présent", "Justificatif joint", "Importé", "Régularisé"].includes(label)) return "success";
  if (["Loué", "Visite prévue", "Prévue", "Contacté", "Réservé", "Planifié", "À payer", "À reverser", "Refacturable", "Ouverte", "Entretien seul"].includes(label)) return "purple";
  if (["En travaux", "Partiel", "À valider", "À échéance", "Échéance proche", "À déduire", "En attente", "En cours", "Reportée", "Relancé", "Promesse de paiement", "Promesse active", "Client intéressé", "Brouillon", "Encaissement propriétaire", "Gestion multi-lots", "Suivi", "Demandé"].includes(label)) return "warning";
  if (["Expiré", "Document signé manquant", "Impayé", "En retard", "Litige", "Perdu", "Suspendu", "Annulé", "Annulée", "Promesse dépassée", "Alerte date dépassée", "Justificatif manquant"].includes(label)) return "danger";
  if (["Inactif", "Indisponible", "Vendu", "Manquant", "Abandonné / annulé"].includes(label)) return "muted";
  return "default";
}

function Avatar({ name, image, initials }) {
  const label =
    initials ??
    name
      .split(" ")
      .map((part) => part[0])
      .join("")
      .slice(0, 2)
      .toUpperCase();
  return image ? <img className="avatar" src={image} alt="" /> : <span className="avatar">{label}</span>;
}

