function hasSignedContractDocument(contract = {}) {
  return Boolean(contract.signedFileName || contract.signedDocument || contract.signedImportedAt);
}

function getSignedContractFileName(contract = {}) {
  return contract.signedFileName || contract.signedDocument || `Contrat signé ${contract.number}.pdf`;
}

function ContractDocumentModal({ contract, action, currentUserName = defaultManagerName, onUpload, onImport, onSignedAction, onClose }) {
  const [workingContract, setWorkingContract] = useState(contract);
  const [mode, setMode] = useState(hasSignedContractDocument(contract) ? "view" : "import");
  const [previewOpen, setPreviewOpen] = useState(false);
  const [values, setValues] = useState({
    fileName: "",
    fileType: "PDF",
    signatureDate: "21/06/2026",
    importDate: "21/06/2026",
    importedBy: currentUserName,
    signers: `${contract.owner}, ${contract.client}, E.K immo`,
    observation: "Contrat signé par les parties et archivé dans le dossier contractuel.",
    upload: null,
  });

  useEffect(() => {
    setWorkingContract(contract);
    setMode(hasSignedContractDocument(contract) ? "view" : "import");
    setPreviewOpen(false);
    setValues((current) => ({
      ...current,
      signers: `${contract.owner}, ${contract.client}, E.K immo`,
    }));
  }, [contract?.number]);

  const hasDocument = hasSignedContractDocument(workingContract);
  const fileName = getSignedContractFileName(workingContract);
  const update = (field) => (event) => setValues((current) => ({ ...current, [field]: event.target.value }));
  const importDocument = () => {
    const nextContract = onImport?.({ contract: workingContract, values, mode: hasDocument ? "replace" : "import" }) ?? workingContract;
    setWorkingContract(nextContract);
    setMode("view");
    setPreviewOpen(false);
  };
  const runSignedAction = (signedAction) => {
    const nextContract = onSignedAction?.(workingContract, signedAction) ?? workingContract;
    setWorkingContract(nextContract);
    if (signedAction === "preview") setPreviewOpen(true);
    if (signedAction === "delete") {
      setMode("import");
      setPreviewOpen(false);
    }
  };

  return (
    <div className="modal-backdrop" role="presentation" onMouseDown={onClose}>
      <section className="modal-card prospect-form-modal signed-contract-modal" role="dialog" aria-modal="true" onMouseDown={(event) => event.stopPropagation()}>
        <button className="modal-close" onClick={onClose}>×</button>
        <h2>Contrat signé</h2>
        <p>{workingContract.number} - {workingContract.property}</p>
        {action && <div className="notice">{action} enregistré dans la timeline du contrat.</div>}

        {mode === "import" ? (
          <>
            <div className="form-section">
              <h3>Import du document signé</h3>
              <div className="form-grid signed-document-form">
                <ServerFileInput
                  label="Importer fichier PDF ou image"
                  value={values.fileName}
                  accept=".pdf,.jpg,.jpeg,.png,.webp"
                  onUpload={onUpload}
                  metadata={{ module: "Contrats", category: "Contrat signé", linkedType: "contract", linkedId: workingContract.number }}
                  onUploaded={(upload) => {
                    setValues((current) => ({
                      ...current,
                      fileName: upload?.originalName ?? current.fileName,
                      fileType: upload?.mimeType?.includes("image") ? "Image" : "PDF",
                      upload,
                    }));
                  }}
                  fallbackText="Aucun contrat signé joint"
                />
                <label>Nom du fichier<input value={values.fileName} onChange={update("fileName")} placeholder={`Contrat signé ${workingContract.number}.pdf`} /></label>
                <label>Date de signature<input type="date" value={toInputDate(values.signatureDate)} onChange={(event) => setValues((current) => ({ ...current, signatureDate: fromInputDate(event.target.value), importDate: fromInputDate(event.target.value) }))} /></label>
                <label>Signataires<input value={values.signers} onChange={update("signers")} /></label>
                <label className="full">Observation<textarea value={values.observation} onChange={update("observation")} /></label>
              </div>
            </div>
            <div className="action-row compact-row">
              <Button onClick={onClose}>Annuler</Button>
              <Button variant="primary" onClick={importDocument}><Archive size={17} /> Importer et archiver</Button>
            </div>
          </>
        ) : (
          <>
            <div className="simple-list signed-contract-details">
              <p><span>Nom du fichier</span><strong>{fileName}</strong></p>
              <p><span>Date d’import</span><strong>{workingContract.signedImportedAt || workingContract.signedAt || "21/06/2026"}</strong></p>
              <p><span>Importé par</span><strong>{workingContract.signedImportedBy || currentUserName}</strong></p>
              <p><span>Signataires</span><strong>{workingContract.signedSigners || `${workingContract.owner}, ${workingContract.client}, E.K immo`}</strong></p>
              {workingContract.signedObservation && <p><span>Observation</span><strong>{workingContract.signedObservation}</strong></p>}
            </div>
            <div className="action-row compact-row">
              <Button onClick={() => runSignedAction("preview")}><Eye size={17} /> Prévisualiser</Button>
              <Button onClick={() => runSignedAction("download")}><Download size={17} /> Télécharger</Button>
              <Button onClick={() => setMode("import")}><Upload size={17} /> Remplacer</Button>
              {workingContract.signedDeleteAllowed !== false && (
                <Button onClick={() => runSignedAction("delete")}><Trash2 size={17} /> Supprimer</Button>
              )}
            </div>
            {previewOpen && (
              <div className="notice">
                Document signé : {fileName}. Le fichier est archivé dans la fiche contrat et reste disponible depuis cette vue.
              </div>
            )}
            <div className="action-row compact-row">
              <Button onClick={onClose}>Fermer</Button>
            </div>
          </>
        )}
      </section>
    </div>
  );
}

function ContractEditModal({ contract, propertiesList = [], ownersList = [], tenantsList = [], prospectsList = [], onSave, onClose }) {
  const propertyOptions = getActiveProperties(propertiesList);
  const financials = getContractFinancials(contract, propertyOptions, tenantsList);
  const property = propertyOptions.find((item) => item.name === contract.property)
    ?? makeEmptyProperty({ name: contract.property ?? "Aucun bien selectionne", owner: contract.owner ?? "" });
  const [values, setValues] = useState({
    number: contract.number,
    type: contract.type,
    status: contract.status,
    property: contract.property,
    owner: contract.owner,
    client: contract.client,
    start: contract.start,
    end: contract.end,
    periodicity: contract.periodicity ?? "Mensuelle",
    nextDueDate: contract.nextDueDate ?? "05/07/2026",
    amount: contract.amount ?? financials.amount,
    deposit: contract.deposit ?? financials.deposit,
    commissionRate: getPercentValue(contract.commissionRate ?? contract.commission ?? financials.commission, "5%"),
    commissionBase: contract.commissionBase ?? "Loyer encaissé",
    financialMode: contract.financialMode ?? property.financialMode ?? "Encaissement par l'agence",
    specialTerms: contract.specialTerms ?? "Conditions standard E.K immo.",
    model: contract.model ?? "Contrat de bail E.K immo",
    signedDocument: contract.signedDocument ?? "Contrat signé archivé",
    observations: contract.observations ?? "Suivi contractuel a jour.",
  });
  const [confirmSensitive, setConfirmSensitive] = useState(false);
  const update = (field) => (event) => setValues((current) => ({ ...current, [field]: event.target.value }));
  const sensitiveChanged = [
    ["property", contract.property],
    ["owner", contract.owner],
    ["client", contract.client],
    ["amount", contract.amount ?? financials.amount],
    ["deposit", contract.deposit ?? financials.deposit],
    ["commissionRate", getPercentValue(contract.commissionRate ?? contract.commission ?? financials.commission, "5%")],
    ["commissionBase", contract.commissionBase ?? "Loyer encaissé"],
    ["financialMode", contract.financialMode ?? property.financialMode ?? "Encaissement par l'agence"],
    ["end", contract.end],
    ["status", contract.status],
  ].some(([field, original]) => values[field] !== original);

  const submit = () => {
    if (sensitiveChanged && !confirmSensitive) {
      setConfirmSensitive(true);
      return;
    }
    onSave({ contract, values });
  };

  return (
    <div className="modal-backdrop" role="presentation" onMouseDown={onClose}>
      <section className="modal-card wide-modal prospect-form-modal" role="dialog" aria-modal="true" onMouseDown={(event) => event.stopPropagation()}>
        <button className="modal-close" onClick={onClose}>×</button>
        <h2>Modifier le contrat</h2>
        <p>{contract.number} - donnees pre-remplies et controle des champs sensibles.</p>
        <div className="form-section">
          <h3>Informations generales</h3>
          <div className="form-grid compact-form">
            <label>Numero contrat<input value={values.number} onChange={update("number")} /></label>
            <label>Type<select value={values.type} onChange={update("type")}><option>Contrat de bail</option><option>Contrat de location</option><option>Mandat de gestion</option><option>Contrat de vente</option></select></label>
            <label>Statut<select value={values.status} onChange={update("status")}><option>Actif</option><option>Renouvelé</option><option>Résilié</option><option>Archivé</option><option>Expiré</option></select></label>
            <label>Bien<select value={values.property} onChange={update("property")}>{propertyOptions.map((item) => <option key={item.code}>{item.name}</option>)}{!propertyOptions.length && <option>{property.name}</option>}</select></label>
            <label>Proprietaire<select value={values.owner} onChange={update("owner")}>{ownersList.map((item) => <option key={item.id ?? item.name}>{item.name}</option>)}{!ownersList.length && <option>{values.owner}</option>}</select></label>
            <label>Locataire / client<select value={values.client} onChange={update("client")}>{[...tenantsList.map((item) => item.name), ...prospectsList.map((item) => item.name)].map((name) => <option key={name}>{name}</option>)}{![...tenantsList, ...prospectsList].length && <option>{values.client}</option>}</select></label>
          </div>
        </div>
        <div className="form-section">
          <h3>Dates</h3>
          <div className="form-grid compact-form">
            <label>Date de debut<input value={values.start} onChange={update("start")} /></label>
            <label>Date de fin<input value={values.end} onChange={update("end")} /></label>
            <label>Periodicite<select value={values.periodicity} onChange={update("periodicity")}><option>Mensuelle</option><option>Trimestrielle</option><option>Annuelle</option></select></label>
            <label>Prochaine échéance<input value={values.nextDueDate} onChange={update("nextDueDate")} /></label>
          </div>
        </div>
        <div className="form-section">
          <h3>Conditions financieres</h3>
          <div className="form-grid compact-form">
            <label>Montant<MoneyInput value={values.amount} onChange={(value) => update("amount")({ target: { value } })} /></label>
            <label>Caution<MoneyInput value={values.deposit} onChange={(value) => update("deposit")({ target: { value } })} /></label>
            <label>Commission permanente<PercentInput value={values.commissionRate} onChange={(value) => update("commissionRate")({ target: { value } })} /></label>
            <label>Base commission<select value={values.commissionBase} onChange={update("commissionBase")}>{recurringCommissionBases.map((option) => <option key={option}>{option}</option>)}</select></label>
            <label>Mode financier<select value={values.financialMode} onChange={update("financialMode")}><option>Encaissement par l'agence</option><option>Encaissement direct propriétaire</option><option>Entretien seul</option></select></label>
            <label className="full">Conditions particulieres<textarea value={values.specialTerms} onChange={update("specialTerms")} /></label>
          </div>
        </div>
        <div className="form-section">
          <h3>Document</h3>
          <div className="form-grid compact-form">
            <label>Modele utilise<input value={values.model} onChange={update("model")} /></label>
            <label>Document signe<input value={values.signedDocument} onChange={update("signedDocument")} /></label>
            <label className="full">Observations<textarea value={values.observations} onChange={update("observations")} /></label>
          </div>
        </div>
        {confirmSensitive && (
          <div className="sensitive-confirmation">
            <div>
              <AlertTriangle size={20} />
              <span>
                <strong>Cette modification peut impacter les paiements, échéances ou situations propriétaires. Confirmer la modification ?</strong>
                <small>Champs sensibles modifiés : bien, propriétaire, locataire, montant, caution, commission, mode financier, date de fin ou statut.</small>
              </span>
            </div>
          </div>
        )}
        <div className="action-row compact-row">
          <Button onClick={onClose}>Annuler</Button>
          <Button variant="primary" onClick={submit}><CheckCircle2 size={17} /> {confirmSensitive ? "Confirmer la modification" : "Enregistrer les modifications"}</Button>
        </div>
      </section>
    </div>
  );
}

